//! Stable live input labels agree with actual pointer activation and paint.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut stack=vec![0];while let Some(n)=stack.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}stack.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn html_input_labels_actual_app_pointer_targets_public_imported_and_promoted_exact_labels(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-html-input-labels-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}label{position:absolute;left:20px;top:20px;width:120px;height:24px}.raw{position:absolute;left:20px;top:100px}.literal{position:absolute;left:20px;top:160px}#neighbor{position:absolute;left:220px;top:20px;width:180px;height:30px}#stable{position:absolute;left:220px;top:100px}#go{position:absolute;left:420px;top:20px;width:120px;height:32px}</style><body><form id=owner><label id=label for='A�z'>Choice</label><input class=raw id=raw type=checkbox><input class=literal id='A�z' type=checkbox></form><input id=neighbor value=seed><a id=stable href=#destination>Go</a><div id=destination></div><button id=go>Change label</button><script>var raw=document.getElementById('raw');raw.id='A\ud800z';var rawLabels=raw.labels,literalLabels=document.getElementById('A�z').labels;if(rawLabels.length||literalLabels.length!==1||literalLabels[0]!==document.getElementById('label'))throw 'initial actual live label lists';var round=0;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native input';var label=document.getElementById('label');if(round===0){label.htmlFor='A\ud800z';}else if(round===1){var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('label');source.htmlFor='A\ud800z';source.textContent='Imported';var copy=document.importNode(source,true);copy.id='label';label.parentNode.replaceChild(copy,label);label=copy;if(source.ownerDocument!==owner||copy.ownerDocument!==document||copy.getAttributeNode('for')===source.getAttributeNode('for'))throw 'independent actual import';}else{var t=document.createElement('template');t.innerHTML='<label id=label for=seed>Promoted</label>';var source=t.content.firstChild,a=source.getAttributeNode('for');source.htmlFor='A\ud800z';var parent=label.parentNode;parent.removeChild(label);parent.appendChild(t.content);label=source;if(a.ownerDocument!==document||a!==label.getAttributeNode('for'))throw 'promoted actual Attr';}if(Object.getPrototypeOf(label)!==HTMLLabelElement.prototype||label.htmlFor!=='A\ud800z'||raw.labels!==rawLabels||rawLabels.length!==1||rawLabels[0]!==label||Array.from(rawLabels)[0]!==label||literalLabels.length!==0||label.form!==document.getElementById('owner')||label.form!==raw.form||Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'form').get.call(label)!==document.getElementById('owner')||label.control!==raw||Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'control').get.call(label)!==raw||label.getAttribute('for')!==label.htmlFor||label.matches('[for="A�z"]'))throw 'literal separation';document.title='Exact label '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let first=(0..app.document.nodes.len()).find(|&n|app.document.dom_attr(n,"id").is_some_and(|v|v.code_units().eq([65,0xd800,122]))).unwrap();let second=(0..app.document.nodes.len()).find(|&n|app.document.attr(n,"class")==Some("literal")).unwrap();assert_ne!(first,second);let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;
 let label=node(&app,"label");assert_eq!(crate::forms::label_targets(&app.document).get(&label),Some(&second));let run=app.page.runs.iter().find(|r|r.text=="Choice").unwrap();let(x,y)=(run.x+2,app.content_top()+run.y+2);let before=app.draw().pixels;app.pointer_down(x,y,false);app.pointer_up(x,y);assert!(!app.forms.controls[&first].checked);assert!(app.forms.controls[&second].checked);assert_ne!(before,app.draw().pixels);
 for round in 0..3{let go=node(&app,"go");let rect=app.page.controls.iter().find(|rect|rect.node==go).unwrap();let(x,button_y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,button_y,false);app.pointer_up(x,button_y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Exact label {round}"));let label=node(&app,"label");assert_eq!(crate::forms::label_targets(&app.document).get(&label),Some(&first),"round {round}, label {label}");let caption=match round{0=>"Choice",1=>"Imported",_=>"Promoted"};let run=app.page.runs.iter().find(|r|r.text==caption).unwrap();let(x,y)=(run.x+2,app.content_top()+run.y+2);let before=app.draw().pixels;app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.forms.controls[&first].checked,round%2==0);assert!(app.forms.controls[&second].checked);assert_ne!(before,app.draw().pixels);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(230,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);}
}
